Identify four processing steps in check_upload below,including the case when both tests fail.
def check_upload(extension, size):
    errors = []
    if extension.lower() not in ["txt", "csv"]:
        errors.append("type")
    if size > 1000000:
        errors.append("size")
    if errors == []:
        return "accepted"
    return errors
